import { defineStory } from "@/lib/story";
import { Badge } from "./badge";

export const story = defineStory(import.meta.url, {
  Component: Badge,
  args: [
    {
      variant: "Default",
      initial: { variant: "default", children: "Default" },
    },
    {
      variant: "Secondary",
      initial: { variant: "secondary", children: "Secondary" },
    },
    {
      variant: "Destructive",
      initial: { variant: "destructive", children: "Destructive" },
    },
    {
      variant: "Outline",
      initial: { variant: "outline", children: "Outline" },
    },
  ],
});

import { cva, type VariantProps } from "class-variance-authority";
import type * as React from "react";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-md border px-2.5 py-0.5 font-semibold text-xs transition-colors focus:outline-hidden focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground shadow-sm hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants };
